export const getPost = (slug: string) =>
  POSTS.find((post) => post.slug === slug);

export const getTopic = (slug: string): TopicMeta | undefined =>
  TOPICS.find((topic) => topic.slug === slug);

export const postsInTopic = (topic: Topic) =>
  POSTS.filter((post) => post.topic === topic);

/**
 * The note's place in the program, 1-based. Deliberately its position in
 * POSTS rather than its position in whatever list is on screen, so note 05
 * reads as note 05 on the front page, on page two, and inside its archive.
 */
export const noteNumber = (post: Post) => POSTS.indexOf(post) + 1;

export const totalReadingMinutes = POSTS.reduce(
  (total, post) => total + post.readingMinutes,
  0,
);

/** How many notes fit on one page of the whole stream. */
export const PAGE_SIZE = 4;

/**
 * One resolved index surface: the front page, a numbered page, or a topic
 * archive. Routes resolve first and render second, so an impossible request
 * (unknown topic, page past the end) is a null here and a 404 there rather
 * than an empty list that looks like a real, empty result.
 */
export type IndexView = {
  /** null is the whole stream. */
  topic: TopicMeta | null;
  page: number;
  pageCount: number;
  /** Notes in this pool, across all its pages. */
  total: number;
  /** The feature. Page one of any pool leads with its first note. */
  lead: Post | null;
  cards: Post[];
};

export function resolveIndex({
  topic,
  page = 1,
}: {
  topic?: string;
  page?: number;
}): IndexView | null {
  const meta = topic === undefined ? null : (getTopic(topic) ?? null);
  if (topic !== undefined && !meta) return null;

  const pool = meta ? postsInTopic(meta.slug) : POSTS;

  // The whole stream paginates. A topic archive is one page by design: an
  // archive is a shelf you scan in one go, and a second URL scheme for it buys
  // nothing. Every archive is now longer than a page of the stream, which is
  // deliberate: a shelf reads as one list. If an archive ever gets long enough
  // that the single page is a burden, give it PAGE_SIZE and add
  // /research/topic/<topic>/page/<n> alongside the stream's own route.
  //
  // A topic's page size is its own length, never Infinity: the offset below is
  // (page - 1) * size, and 0 * Infinity is NaN, which slices to nothing.
  const size = meta ? Math.max(1, pool.length) : PAGE_SIZE;
  const pageCount = Math.max(1, Math.ceil(pool.length / size));
  if (!Number.isInteger(page) || page < 1 || page > pageCount) return null;

  const start = (page - 1) * size;
  const items = pool.slice(start, start + size);
  const lead = page === 1 ? (items[0] ?? null) : null;

  return {
    topic: meta,
    page,
    pageCount,
    total: pool.length,
    lead,
    cards: lead ? items.slice(1) : items,
  };
}

/** The note before and after this one in the program. No wrap-around. */
export const neighbours = (post: Post) => {
  const at = POSTS.indexOf(post);
  return { previous: POSTS[at - 1] ?? null, next: POSTS[at + 1] ?? null };
};

/**
 * Further reading for an article tail: the rest of this note's topic first,
 * then the program in reading order, so the section is never short. Pass the
 * neighbours in `exclude` when the page already links them, so the same note
 * is not offered twice under two different headings.
 */
export function relatedPosts(
  post: Post,
  limit = 3,
  exclude: (Post | null)[] = [],
): Post[] {
  const skip = new Set<Post>([post, ...exclude.filter((it) => it !== null)]);
  const sameTopic = postsInTopic(post.topic).filter((it) => !skip.has(it));
  const rest = POSTS.filter((it) => !skip.has(it) && !sameTopic.includes(it));
  return [...sameTopic, ...rest].slice(0, limit);
}
